from __future__ import absolute_import
import logging
from selenium.webdriver.common.by import By
from selenium.common.exceptions import StaleElementReferenceException
from taf.selenium.sbts_fsm3.pages import v21a
from taf.selenium.sbts_fsm3.pages import v22r1
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.common.exceptions import RadioIdNotFound
from taf.selenium.sbts_fsm3.common.utils import wait_for_operation_success


class Diagnostic(v22r1.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._test_setup = TestSetupPage(driver)
        self._test_result = RfDiagnosticTestResultsPage(driver, download_checker)
        self._test_statistics_test_result = RfStatisticsDiagnosticTestResultsPage(driver)
        self._debug_tracing = DebugTracingPage(driver)

    @property
    def test_statistics_test_result(self):
        return self._test_statistics_test_result


class TestSetupPage(v21a.diagnostic.TestSetupPage):
    def __init__(self, driver):
        super(TestSetupPage, self).__init__(driver)
        self._view_panel = TestSetupPageViewPanel(driver)

    def start_statistics_diagnostic_test(self, timeout=60):
        return self._view_panel.start_statistics_diagnostic_test(timeout)

    def configure_statistics_diagnostic_test(self, activate, radio, timeout=60):
        self._view_panel.configure_statistics_diagnostic_test(activate, radio, timeout)


class TestSetupPageViewPanel(v21a.diagnostic.TestSetupPageViewPanel):
    _START_TEST_BUTTON = '//button[contains(text(), "Start RF Diagnostic Test")]'
    _TEST_STARTED = 'RF diagnostic test started'
    _TEST_COMPLETED = "Test completed"
    _OPERATION_STARTED = "Operation started"
    _OPERATION_COMPLETED = "Operation completed"
    _TEST_STARTED_STATUS = ('//span[contains(text(), "{}") '
                            'or contains(text(), "{}")]'.format(_TEST_STARTED, _OPERATION_STARTED))
    _THRESHOLDS_FOR_BTS_LABEL = '//div[*[contains(text(), "Thresholds")]]//*[contains(text(), "{}")]'
    _THRESHOLDS_FOR_BTS_INPUT = _THRESHOLDS_FOR_BTS_LABEL + '/following-sibling::div//input'
    _BTS_THRESHOLDS_ERROR = _THRESHOLDS_FOR_BTS_LABEL + '/following-sibling::div//span[contains(@class, "triangle")]'
    _TECHNOLOGY = '//*[@for="{}Technology"]'

    _STATISTICS_TEST_STARTED = "Statistics diagnostic test started"
    _STATISTICS_TEST_COMPLETED = "Test completed"
    _STATISTICS_TEST_STARTED_STATUS = '//span[contains(text(), "{}")]'.format(_STATISTICS_TEST_STARTED)
    _STATISTICS_TEST_COMPLETED_STATUS = '//span[contains(text(), "{}")]'.format(_STATISTICS_TEST_COMPLETED)
    _START_STATISTICS_TEST_FOR_RADIO_DROPDOWN_BUTTON = '//div[div[contains(text(), "Start test for radio")]]//button'
    _START_STATISTICS_TEST_FOR_CELL_DROPDOWN_ITEM = '//div[div[contains(text(), "Start test for radio")]]//li'
    _START_STATISTICS_TEST_BUTTON = '//button[contains(text(), "Start Statistics Diagnostic Test")]'

    def __init__(self, driver):
        super(TestSetupPageViewPanel, self).__init__(driver)

    def configure_rf_diagnostic_test(self, activate, cell, bts_thresholds, bands_thresholds, timeout, technology='NR'):
        if not self.elements_is_visible((By.XPATH, self._TDS_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CHECK_XPATH,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CLICK_XPATH)
        self.click_enabled_element((By.XPATH, self._TECHNOLOGY.format(technology.lower())), timeout)

        self.select_element_from_dropdown_list_by_text_and_click(cell,
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_BUTTON),
                                                                 (By.XPATH, self._START_TEST_FOR_CELL_DROPDOWN_ITEM),
                                                                 timeout)
        self.configure_and_check_bts_thresholds(bts_thresholds, timeout)
        self._configure_bands_thresholds(bands_thresholds, timeout)

    def start_statistics_diagnostic_test(self, timeout):
        self.click_enabled_element((By.XPATH, self._START_STATISTICS_TEST_BUTTON), timeout)
        self.wait_for_visibility_by_xpath(self._STATISTICS_TEST_STARTED_STATUS, timeout)
        logging.info(self._TEST_STARTED)
        self.wait_for_visibility_by_xpath(self._STATISTICS_TEST_COMPLETED_STATUS, timeout)
        logging.info(self._TEST_COMPLETED)
        return self._TEST_COMPLETED

    def configure_statistics_diagnostic_test(self, activate, radio, timeout=60):
        if not self.elements_is_visible((By.XPATH, self._TDS_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CHECK_XPATH,
                                                     self._ACTIVATE_REMOTE_RF_TEST_CLICK_XPATH)

        self.select_element_from_dropdown_list_by_text_and_click(
            radio,
            (By.XPATH, self._START_STATISTICS_TEST_FOR_RADIO_DROPDOWN_BUTTON),
            (By.XPATH, self._START_STATISTICS_TEST_FOR_CELL_DROPDOWN_ITEM),
            timeout)


class RfDiagnosticTestResultsPage(v21a.diagnostic.TestResultPage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'RF Diagnostic Test', 'RF Diagnostic Test Results']


class RfStatisticsDiagnosticTestResultsPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'RF Diagnostic Test', 'RF Statistics Diagnostic Test Results']

    def __init__(self, driver):
        super(RfStatisticsDiagnosticTestResultsPage, self).__init__(driver)
        self._view_panel = RfStatisticsDiagnosticTestResultsPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_statistics_general_test_information(self, radio_id=None, timeout=60):
        return self._view_panel.get_general_test_information(radio_id, timeout)

    def get_rf_temperature_supervision(self, radio_id=None, timeout=60):
        return self._view_panel.get_rf_temperature_supervision(radio_id, timeout)

    def get_rf_ethernet_packet_monitoring(self, radio_id=None, timeout=60):
        return self._view_panel.get_rf_ethernet_packet_monitoring(radio_id, timeout)


class RfStatisticsDiagnosticTestResultsPageViewPanel(ViewPanel):
    _RADIO_FILTER_XPATH = '//div[contains(@class, "radio-list-area")]//li[@aria-label="{}"]'
    _BASE_XPATH = '//*[text()="{}"]/following-sibling::p-table[1]'
    _GENERAL_INFO_THEAD = (_BASE_XPATH.format('General test information') + '//thead//th')
    _GENERAL_INFO_TBODY_TR = (_BASE_XPATH.format('General test information') + '//tbody//tr')
    _TEMPERATURE_SUPERVISION_THEAD = _BASE_XPATH.format('RF temperature supervision') + '//thead//th'
    _TEMPERATURE_SUPERVISION_TBODY_TR = _BASE_XPATH.format('RF temperature supervision') + '//tbody//tr'
    _ETHERNET_PACKET_INFO_THEAD = (_BASE_XPATH.format('RF ethernet packet monitoring') + '//thead//th')
    _ETHERNET_PACKET_TBODY_TR = (_BASE_XPATH.format('RF ethernet packet monitoring') + '//tbody//tr')
    _TEMPERATURE = 'Temperature value'

    def __init__(self, driver):
        super(RfStatisticsDiagnosticTestResultsPageViewPanel, self).__init__(driver)

    @wait_for_operation_success(2, StaleElementReferenceException)
    def _select_radio_id(self, radio_id=None, timeout=60):
        if not radio_id:
            return

        self.wait_for_visibility_by_xpath(self._RADIO_FILTER_XPATH.format(radio_id), timeout)
        elem = self.wait_for_enable((By.XPATH, self._RADIO_FILTER_XPATH.format(radio_id)), timeout)
        if not elem:
            raise RadioIdNotFound('radio id:{}'.format(radio_id))
        else:
            elem.click()

    def _get_head_and_body_xpath(self, func_name):
        if 'general' in func_name:
            head_th_xpath = self._GENERAL_INFO_THEAD
            body_tr_xpath = self._GENERAL_INFO_TBODY_TR
        if 'temperature' in func_name:
            head_th_xpath = self._TEMPERATURE_SUPERVISION_THEAD
            body_tr_xpath = self._TEMPERATURE_SUPERVISION_TBODY_TR
        if 'ethernet' in func_name:
            head_th_xpath = self._ETHERNET_PACKET_INFO_THEAD
            body_tr_xpath = self._ETHERNET_PACKET_TBODY_TR
        return head_th_xpath, body_tr_xpath

    def get_info(func):
        def wrapper(self, radio_id=None, timeout=60):
            self._select_radio_id(radio_id, timeout)
            head_th_xpath, body_tr_xpath = self._get_head_and_body_xpath(func.__name__)

            thead_values = self.get_fields_info_from_row(head_th_xpath, timeout)
            thead_values = [self._TEMPERATURE if self._TEMPERATURE in value else value for value in thead_values]
            tr_elements = self.driver.find_elements_by_xpath(body_tr_xpath)
            tbody_values = []
            for i, tr_element in enumerate(tr_elements):
                tbody_values.append({k: '' for k in thead_values})
                for j, td_element in enumerate(tr_element.find_elements_by_xpath("td")):
                    td_value = td_element.text.strip()
                    tbody_values[i][thead_values[j]] = td_value
            return tbody_values

        return wrapper

    @get_info
    def get_general_test_information(self, radio_id=None, timeout=60):
        pass

    @get_info
    def get_rf_temperature_supervision(self, radio_id=None, timeout=60):
        pass

    @get_info
    def get_rf_ethernet_packet_monitoring(self, radio_id=None, timeout=60):
        pass


class DebugTracingPage(v21a.diagnostic.DebugTracingPage):
    def __init__(self, driver):
        super(DebugTracingPage, self).__init__(driver)
        self._view_panel = DebugTracingPageViewPanel(driver)

    def configure_iq_capture(self, bbmod, enable_capture_on_event, ul_subcell_index_list=None,
                             dl_subcell_index_list=None, lte_ul_cell_ids=None, lte_dl_cell_ids=None):
        self._detail_panel.close_details_panel()
        self._view_panel.configure_iq_capture(bbmod=bbmod,
                                              enable_capture_on_event=enable_capture_on_event,
                                              ul_subcell_index_list=ul_subcell_index_list,
                                              dl_subcell_index_list=dl_subcell_index_list,
                                              lte_ul_cell_ids=lte_ul_cell_ids,
                                              lte_dl_cell_ids=lte_dl_cell_ids)

    def save_iq_capture(self, bbmod, sfn_value, slot_value, capture_mode):
        self._view_panel.save_iq_capture(bbmod, sfn_value, slot_value, capture_mode)


class DebugTracingPageViewPanel(v21a.diagnostic.DebugTracingPageViewPanel):
    _LTE_UL_CELL_IDS = "LTE UL cell IDs"
    _LTE_DL_CELL_IDS = "LTE DL cell IDs"
    _LTE_CELL_IDS_INPUT_XPATH = '//section[@class="uPlane-component"]//div[contains(text(), "{}")]/parent::*//input'
    _CAPTURE_MODE = 'Capture mode'
    _CAPTURE_MODE_DROPDOWN_BUTTON_XPATH = ('//section[@class="uPlane-component"]//div[contains(text(), '
                                           '"Capture mode")]/following-sibling::div//button')
    _CAPTURE_MODE_DROPDOWN_SELECTION_XPATH = '//span[text()="{}"]'

    def __init__(self, driver):
        super(DebugTracingPageViewPanel, self).__init__(driver)

    def configure_iq_capture(self, bbmod, enable_capture_on_event, ul_subcell_index_list=None,
                             dl_subcell_index_list=None, lte_ul_cell_ids=None, lte_dl_cell_ids=None):
        elem = self.driver.find_element_by_xpath(self._L1_IQ_CAPTURE_XPATH)
        self._scroll_elem_into_view(elem)
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_bbmod(bbmod)
        self._choose_operation(self._COMPONENT_TYPE, self._CONFIGURE)
        self._select_subcell_list(self._UL_SUBCELL, ul_subcell_index_list)
        self._select_subcell_list(self._DL_SUBCELL, dl_subcell_index_list)
        self._input_cell_ids(self._LTE_UL_CELL_IDS, lte_ul_cell_ids)
        self._input_cell_ids(self._LTE_DL_CELL_IDS, lte_dl_cell_ids)
        self.select_checkbox_by_specified_status(enable_capture_on_event,
                                                 self._CAPTURE_EVENT_INPUT_XPATH,
                                                 self._CAPTURE_EVENT_CHECKOUT_XPATH)
        elem = self.driver.find_element_by_xpath(self._APPLY_CONFIGURATION_BUTTON_XPATH)
        self._scroll_elem_into_view(elem)
        self.click_enabled_element((By.XPATH, self._APPLY_CONFIGURATION_BUTTON_XPATH))

    def _input_cell_ids(self, cell_ids_lable, cells_ids):
        if not cells_ids:
            return
        cell_ids_input_xpath = self._LTE_CELL_IDS_INPUT_XPATH.format(cell_ids_lable)
        for index, elem in enumerate(self.driver.find_elements_by_xpath(cell_ids_input_xpath)):
            value = cells_ids[index]
            if value is not None:
                elem.clear()
                elem.send_keys(value)

    def save_iq_capture(self, bbmod, sfn_value, slot_value, capture_mode):
        if capture_mode is None:
            raise AttributeError('param capture_mode can not be None')
        elem = self.driver.find_element_by_xpath(self._L1_IQ_CAPTURE_XPATH)
        self._scroll_elem_into_view(elem)
        self.click_enabled_element((By.XPATH, self._L1_IQ_CAPTURE_XPATH))
        self._choose_bbmod(bbmod)
        self._choose_operation(self._COMPONENT_TYPE, self._SAVE_IQ)
        self._input_subcell_index_and_other_fields(self._SFN, sfn_value)
        self._input_subcell_index_and_other_fields(self._SLOT, slot_value)
        self.select_element_from_dropdown_list_by_text_and_click(
            capture_mode,
            (By.XPATH, self._CAPTURE_MODE_DROPDOWN_BUTTON_XPATH.format(self._CAPTURE_MODE)),
            (By.XPATH, self._CAPTURE_MODE_DROPDOWN_SELECTION_XPATH.format(capture_mode))
        )
        self.click_enabled_element((By.XPATH, self._SAVE_IQ_CAPTURE_DATA_BUTTON_XPATH))
